export function Abac({
  resourceLabel = "{{resourceLabel}}",
  resourceDept = "{{resourceDept}}",
  userDept = "{{userDept}}",
  accent = "{{accent}}",
}) {
  const granted = resourceDept === userDept;
  return (
    <div style={{ font: "13px/1.5 system-ui, sans-serif", color: "#241430", background: "#FAF7F2", padding: 18, borderRadius: 12, width: 300, boxSizing: "border-box" }}>
      <p style={{ margin: "0 0 12px", fontSize: 11, color: "#24143099" }}>Rule: allow if user.department == resource.department</p>
      <div style={{ display: "flex", gap: 8, marginBottom: 12 }}>
        <div style={{ flex: 1, padding: 10, borderRadius: 8, background: "#24143010", textAlign: "center", fontSize: 11 }}>resource.department<br /><strong style={{ display: "block", marginTop: 2, textTransform: "capitalize" }}>{resourceDept}</strong></div>
        <div style={{ flex: 1, padding: 10, borderRadius: 8, background: "#24143010", textAlign: "center", fontSize: 11 }}>user.department<br /><strong style={{ display: "block", marginTop: 2, textTransform: "capitalize" }}>{userDept}</strong></div>
      </div>
      {granted
        ? <div style={{ padding: 12, borderRadius: 8, textAlign: "center", fontWeight: 700, background: accent }}>&#10003; Access granted to &ldquo;{resourceLabel}&rdquo;</div>
        : <div style={{ padding: 12, borderRadius: 8, textAlign: "center", fontWeight: 700, background: "#24143014", color: "#24143099" }}>&#10005; Access denied to &ldquo;{resourceLabel}&rdquo;</div>}
    </div>
  );
}
